after.write.js:
export async function write(db, record) {
  try { await db.put(record); }
  catch (cause) { throw new Error('Could not persist record', { cause }); }
}

after.send.js:
export async function send(client, data) {
  try { return await client.send(data); }
  catch (error) {
    if (error.code !== 'ECONNRESET') throw error;
    return await client.send(data);
  }
}

after.pay.js:
export async function pay(gateway) {
  try { return await gateway.charge(); }
  catch (error) { console.error('charge rejected', error); throw error; }
}

after.read.js:
export async function read(handle) {
  try { return await handle.read(); }
  finally { await handle.close(); }
}

after.average.js:
export function average(values) {
  if (values.length === 0) return null;
  return values.reduce((a, b) => a + b, 0) / values.length;
}
